#ifndef MESH_CUBED_SPHERE_VOLUME_MLS_PROBE_HPP_
#define MESH_CUBED_SPHERE_VOLUME_MLS_PROBE_HPP_
#include <limits>
#include <map>
#include "mesh/cubed_sphere/scri_surface.hpp"
namespace cubed_sphere {
// Standalone probe only. Geometry-only degree5 Cartesian MLS (56 terms),
// scaled by n*dq/dx of the TARGET chart at each physical query. Global active
// donors and actual scri nodes span seams/corners; source fields never change.
class VolumeMLSProbe {
 public:
 struct Node {std::array<Real,3>x;int index;bool boundary;};
 struct Row {std::vector<int> ids;std::vector<Real> weights;int rank=0;Real condition=0,l1=0,reproduction=0;};
 const CompositeDifference &g;const ScriSurface &surface;const std::vector<Real>&volume,&boundary;int fields,donors;bool outer_only,owner_scaling;std::vector<Node> points;
 mutable std::map<std::array<Real,4>,Row> cache;
 mutable size_t rows_built=0,identity_rows=0;mutable Real maximum_l1=0,maximum_condition=0,maximum_reproduction=0;
 VolumeMLSProbe(const ScriSurface&s,const std::vector<Real>&v,const std::vector<Real>&b,int f,int count=256,bool outer=false,bool owner=false):g(s.grid),surface(s),volume(v),boundary(b),fields(f),donors(count),outer_only(outer),owner_scaling(owner){if(v.size()!=size_t(g.count*f)||b.size()!=s.rows.size()*f||count<56||count>512)throw std::invalid_argument("volume MLS donor/layout bound");for(size_t i=0;i<g.active.size();++i){const size_t block=i/(g.n*g.n*g.n);if(outer_only&&g.mesh.blocks[block].layer!=int(g.mesh.radii.size())-1)continue;Node n{};std::copy(g.geometry[i].x,g.geometry[i].x+3,n.x.begin());n.index=g.active[i];n.boundary=false;points.push_back(n);}for(size_t i=0;i<s.rows.size();++i){Node n{};std::copy(s.rows[i].geometry.x,s.rows[i].geometry.x+3,n.x.begin());n.index=i;n.boundary=true;points.push_back(n);}if(points.size()<size_t(count))throw std::invalid_argument("volume MLS insufficient global donors");}
 Row Build(int block,const Real*q)const{auto geometry=g.mesh.Geometry(block,q);const int owner=g.mesh.Owner(geometry.x);if(owner<0||(outer_only&&g.mesh.blocks[owner].layer!=int(g.mesh.radii.size())-1))throw std::runtime_error("volume MLS query outside donor collar");if(owner_scaling){Real local[3];g.mesh.Inverse(owner,geometry.x,local);geometry=g.mesh.Geometry(owner,local);}std::vector<std::pair<Real,int>> distance;distance.reserve(points.size());std::vector<std::array<Real,3>> coordinates(points.size());for(size_t i=0;i<points.size();++i){Real d=0;for(int A=0;A<3;++A){for(int a=0;a<3;++a)coordinates[i][A]+=g.n*geometry.J[A][a]*(points[i].x[a]-geometry.x[a]);d+=coordinates[i][A]*coordinates[i][A];}if(d<1e-26){Row row;row.ids={int(i)};row.weights={1};row.rank=56;row.condition=row.l1=1;++identity_rows;return row;}distance.push_back({d,int(i)});}std::partial_sort(distance.begin(),distance.begin()+donors,distance.end());Real scale=std::sqrt(distance[donors-1].first);if(!(scale>0&&std::isfinite(scale)))throw std::runtime_error("volume MLS invalid mapped scale");
  constexpr int p=56;Row row;std::vector<Real> original[p],v[p],Q[p],sw(donors);Real R[p][p]{};int perm[p];for(int k=0;k<p;++k){perm[k]=k;v[k].resize(donors);original[k].resize(donors);}for(int i=0;i<donors;++i){row.ids.push_back(distance[i].second);const auto &z=coordinates[row.ids.back()];sw[i]=std::exp(-2*distance[i].first/(scale*scale));int k=0;for(int degree=0;degree<=5;++degree)for(int a=0;a<=degree;++a)for(int b=0;b<=degree-a;++b){int c=degree-a-b;original[k][i]=std::pow(z[0]/scale,a)*std::pow(z[1]/scale,b)*std::pow(z[2]/scale,c);v[k][i]=sw[i]*original[k][i];++k;}}
  Real largest=0;for(int k=0;k<p;++k){int pivot=k;Real biggest=-1;for(int j=k;j<p;++j){Real n=0;for(Real a:v[j])n+=a*a;if(n>biggest){biggest=n;pivot=j;}}if(pivot!=k){std::swap(v[k],v[pivot]);std::swap(perm[k],perm[pivot]);for(int i=0;i<k;++i)std::swap(R[i][k],R[i][pivot]);}R[k][k]=std::sqrt(biggest);largest=std::max(largest,R[k][k]);if(!(R[k][k]>1e-12*largest))throw std::runtime_error("volume MLS rank deficient at "+std::to_string(block)+","+std::to_string(q[0])+","+std::to_string(q[1])+","+std::to_string(q[2])+" rank="+std::to_string(k));++row.rank;Q[k]=v[k];for(auto&a:Q[k])a/=R[k][k];for(int j=k+1;j<p;++j)for(int pass=0;pass<2;++pass){Real dot=0;for(int i=0;i<donors;++i)dot+=Q[k][i]*v[j][i];R[k][j]+=dot;for(int i=0;i<donors;++i)v[j][i]-=dot*Q[k][i];}}
  Real inverse[p][p]{},rnorm=0,inorm=0;for(int col=0;col<p;++col)for(int i=p-1;i>=0;--i){Real rhs=i==col?1:0;for(int j=i+1;j<p;++j)rhs-=R[i][j]*inverse[j][col];inverse[i][col]=rhs/R[i][i];}for(int i=0;i<p;++i){Real a=0,b=0;for(int j=0;j<p;++j){a+=std::abs(R[i][j]);b+=std::abs(inverse[i][j]);}rnorm=std::max(rnorm,a);inorm=std::max(inorm,b);}row.condition=rnorm*inorm;if(!(row.condition<1e8))throw std::runtime_error("volume MLS QR condition guard");Real y[p]{};for(int k=0;k<p;++k){Real b=perm[k]==0?1:0;for(int j=0;j<k;++j)b-=R[j][k]*y[j];y[k]=b/R[k][k];}row.weights.resize(donors);for(int i=0;i<donors;++i)for(int k=0;k<p;++k)row.weights[i]+=sw[i]*Q[k][i]*y[k];Real sum=0;for(Real w:row.weights)sum+=w;row.weights[0]+=1-sum;for(Real w:row.weights)row.l1+=std::abs(w);if(!(row.l1<=8&&std::isfinite(row.l1)))throw std::runtime_error("volume MLS value L1 guard: "+std::to_string(row.l1)+" condition="+std::to_string(row.condition)+" block="+std::to_string(block)+" q="+std::to_string(q[0])+","+std::to_string(q[1])+","+std::to_string(q[2])+" x="+std::to_string(geometry.x[0])+","+std::to_string(geometry.x[1])+","+std::to_string(geometry.x[2]));for(int k=0;k<p;++k){Real value=0;for(int i=0;i<donors;++i)value+=row.weights[i]*original[k][i];row.reproduction=std::max(row.reproduction,std::abs(value-(k==0?1.:0)));}if(!(row.reproduction<1e-10))throw std::runtime_error("volume MLS polynomial reproduction guard");++rows_built;maximum_l1=std::max(maximum_l1,row.l1);maximum_condition=std::max(maximum_condition,row.condition);maximum_reproduction=std::max(maximum_reproduction,row.reproduction);return row;
 }
 std::vector<Real> Sample(int block,const Real*q)const{std::array<Real,4> key{Real(block),q[0],q[1],q[2]};for(int a=0;a<3;++a){const Real lattice=std::round(2*g.n*q[a]);if(std::abs(2*g.n*q[a]-lattice)<1e-12)key[a+1]=lattice/(2*g.n);}auto found=cache.find(key);if(found==cache.end())found=cache.emplace(key,Build(block,q)).first;const auto &row=found->second;auto value=[&](int node,int f){const auto &n=points[node];return n.boundary?boundary[n.index*fields+f]:volume[f*g.count+n.index];};std::vector<Real> out(fields);for(int f=0;f<fields;++f){const Real anchor=value(row.ids[0],f);out[f]=anchor;for(size_t i=0;i<row.ids.size();++i)out[f]+=row.weights[i]*(value(row.ids[i],f)-anchor);}return out;}
};
} // namespace cubed_sphere
#endif
